// Single topic path
const body = $json.body;
return [{
  json: {
    topic: body.post_topic,
    rowIndex: null, // No sheet row to update for single topic
    sheet_id: null,
    post_tone: body.post_tone || 'Professional',
    include_hashtags: body.include_hashtags === true || body.include_hashtags === 'true',
    image_option: body.image_option || 'AI-Generated Image',
    callbackUrl: body.callbackUrl || '',
    linkedin_access_token: body.tokens?.linkedin || body.access_token || '',
    google_sheets_access_token: body.tokens?.google_sheets || ''
  }
}];

// ============================================================
// Filter out already-Posted topics and take the first N
// from the TOP of the sheet (preserving order).
//
// Expected sheet columns:
//   A: Topic
//   B: Status   (empty = not posted, 'Posted' = done)
//   C: Post URL (filled in after posting)
//   D: Posted Date
// ============================================================
const body = $('Webhook').first().json.body;
const limit = 1;

// Extract sheet ID from URL for later write-back
const sheetUrl = body.sheet_url || '';
const sheetIdMatch = sheetUrl.match(/\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/);
const sheet_id = sheetIdMatch ? sheetIdMatch[1] : null;

// Sheets API returns { values: [[header1,...], [row1col1,...], ...] }
const rows = $json.values || [];
if (rows.length < 2) {
  throw new Error('Sheet is empty or has no data rows. Add topics first.');
}

// Find column indices from header row (case-insensitive)
const headers = rows[0].map(h => (h || '').toLowerCase().trim());
const topicIdx  = headers.findIndex(h => h === 'topic'  || h === 'topics');
const statusIdx = headers.findIndex(h => h === 'status');

// Default to column 0 for topic if header not found
const tIdx = topicIdx >= 0 ? topicIdx : 0;
const sIdx = statusIdx >= 0 ? statusIdx : 1;

// Filter unposted rows (from top), track their 1-based sheet row numbers
// Row index in sheet = array index + 2 (1 for header row + 1 for 1-based)
const unpostedRows = [];
for (let i = 1; i < rows.length; i++) {
  const row = rows[i];
  const topic  = (row[tIdx]  || '').trim();
  const status = (row[sIdx]  || '').trim().toLowerCase();
  if (topic && status !== 'posted') {
    unpostedRows.push({ row, sheetRowNumber: i + 1 }); // +1 because arrays are 0-based but sheets are 1-based, plus 1 for header
  }
  if (unpostedRows.length >= limit) break;
}

if (unpostedRows.length === 0) {
  throw new Error('All topics in the sheet have already been posted! Add new topics to continue.');
}

// Return one item per topic to be posted
return unpostedRows.map(({ row, sheetRowNumber }) => ({
  json: {
    topic: row[tIdx],
    rowIndex: sheetRowNumber,   // Sheet row number for write-back
    sheet_id: sheet_id,         // Spreadsheet ID for API calls
    post_tone: body.post_tone || 'Professional',
    include_hashtags: body.include_hashtags === true || body.include_hashtags === 'true',
    image_option: body.image_option || 'AI-Generated Image',
    callbackUrl: body.callbackUrl || '',
    linkedin_access_token: body.tokens?.linkedin || body.access_token || '',
    google_sheets_access_token: body.tokens?.google_sheets || body.access_token || ''
  }
}));

