// Extract post text from Gemini + carry forward all context fields
const postText = $json.candidates?.[0]?.content?.parts?.[0]?.text || 'Post generation failed.';

// Grab context correctly depending on which path triggered us
const isSingle = $('Single Topic Setup').all().length > 0;
const ctx = isSingle 
  ? $('Single Topic Setup').item?.json || $('Single Topic Setup').all()[0]?.json
  : $('Filter Unposted Topics').item?.json || $('Filter Unposted Topics').all()[0]?.json;

return {
  json: {
    ...(ctx || {}),
    post_text: postText.trim()
  }
};

// Pollinations directly returns the image as binary data.
const ctx = $('Extract Post Text').item.json;
if (!$binary || !Object.keys($binary).length) {
  return { json: { ...ctx, hasImage: false } };
}

// We typically find it mapped to the 'data' key by n8n HTTP Request
const imageBinary = $binary.data;

return {
  json: { ...ctx, hasImage: true },
  binary: {
    image: {
      data: imageBinary.data,
      mimeType: imageBinary.mimeType,
      fileName: 'linkedin_post_image.png'
    }
  }
};

// Merge both branches back into one consistent payload
const ctx = $('Extract Post Text').item.json;
const accessToken = $json.linkedin_access_token || ctx.linkedin_access_token;
const postText = $json.post_text || ctx.post_text;
return {
  json: {
    ...ctx,
    linkedin_access_token: accessToken,
    post_text: postText
  }
};

// Build the UGC post body and keep all context for later write-back
const personSub = $json.sub;
const authorUrn = personSub.startsWith('urn:li:person:') ? personSub : `urn:li:person:${personSub}`;
const prev = $('Prepare LinkedIn Payload').item.json;

return {
  json: {
    // LinkedIn UGC post payload
    author: authorUrn,
    lifecycleState: 'PUBLISHED',
    specificContent: {
      'com.linkedin.ugc.ShareContent': {
        shareCommentary: { text: prev.post_text },
        shareMediaCategory: 'NONE'
      }
    },
    visibility: { 'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC' },
    // Carry-forward context
    _accessToken: prev.linkedin_access_token,
    _sheetsToken: prev.google_sheets_access_token,
    _callbackUrl: prev.callbackUrl,
    _topic: prev.topic,
    _rowIndex: prev.rowIndex,
    _sheet_id: prev.sheet_id
  }
};

// Build the sheet update payload:
//   Column B (Status) = 'Posted'
//   Column C (Post URL) = LinkedIn post URL
//   Column D (Posted Date) = Today's date
//
// LinkedIn API returns: { id: 'urn:li:ugcPost:XXXXXXXXX' }
const prev = $('Build UGC Post Body').item.json;
const postUrn = $json.id || '';

// Convert URN to viewable URL: urn:li:ugcPost:1234 → https://www.linkedin.com/feed/update/urn:li:ugcPost:1234/
const postUrl = postUrn ? `https://www.linkedin.com/feed/update/${postUrn}/` : 'N/A';

const today = new Date().toISOString().split('T')[0]; // YYYY-MM-DD

return {
  json: {
    sheetsToken: prev._sheetsToken,
    sheet_id: prev._sheet_id,
    rowIndex: prev._rowIndex,
    postUrl: postUrl,
    postUrn: postUrn,
    today: today,
    topic: prev._topic,
    callbackUrl: prev._callbackUrl
  }
};

